import {readFile,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import {startComparisonServer} from '../../framework-comparison/src/server.mjs';
import {startSsrWorker,stopSsrWorker} from '../../framework-comparison/src/ssr-worker-controller.mjs';
import {measureInterleavedSsrParticipants} from '../../framework-comparison/src/ssr-interleaved-measurement.mjs';
import {availableSsrRuntimes} from '../../framework-comparison/src/ssr-run-environment.mjs';
import {resetSsrClientConnections} from '../../framework-comparison/src/ssr-benchmark-client.mjs';
const suite=resolve('framework-comparison');
const config={sampleCount:500,warmupCount:100,concurrency:16,concurrencyWaves:500,capacityPrimeConcurrency:32,capacityPrimeMs:3000,saturationConcurrency:[],attributionConcurrency:[],payloadSweepBytes:[],orderOffset:0};
const service=await startComparisonServer();const entries=[];
try{
 for(const id of ['exact','react','sveltekit','nuxt','tanstack-start']){
 const metadata=JSON.parse(await readFile(`${suite}/participants/${id}/participant.json`));
 const worker=await startSsrWorker({runtime:availableSsrRuntimes('node')[0],participantId:id,transport:metadata.ssrTransports.node,workerPath:resolve(suite,'src/ssr-benchmark-worker.mjs'),workingDirectory:suite,serviceUrl:service.url});
 entries.push({key:id,worker,supportsRendererDiagnostics:false});
 }
 console.log('Five workers ready; 500 sequential and burst rounds');
 const result=await measureInterleavedSsrParticipants(entries,config);
 await writeFile('.tmp/framework-audit/ssr-tails.json',JSON.stringify({createdAt:new Date().toISOString(),config,...result},null,2));
 console.log(Object.fromEntries(Object.entries(result.participants).map(([id,p])=>[id,{sequential:p.sequential.client.totalMs,burst:p.concurrent.burstElapsedMs}])));
}finally{await Promise.all(entries.map(e=>stopSsrWorker(e.worker)));resetSsrClientConnections();await service.close();}

